  `bid_publish_datetime` datetime DEFAULT NULL COMMENT '发布时间',
  `bid_publisher` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '' COMMENT '发布者',
  `view_count` bigint(20) DEFAULT '0' COMMENT '浏览次数',
  `category` smallint(6) DEFAULT NULL COMMENT '发布分类  1招标预告 2招标公告 3 中标公告 4企业采购',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '' COMMENT '创建者',
