--
-- Table structure for table `bid_order`
--

DROP TABLE IF EXISTS `bid_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `bid_order` (
  `order_id` bigint(20) NOT NULL COMMENT '订单编号',
  `goods_id` bigint(20) DEFAULT NULL COMMENT '商品编号',
  `goods_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '商品名称',
  `enterprise_id` bigint(20) DEFAULT NULL COMMENT '企业编号',
  `enterprise_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '企业名称',
  `price` decimal(10,2) DEFAULT NULL COMMENT '价格',
  `payment_method` tinyint(4) DEFAULT NULL COMMENT '支付方式：1微信 2支付宝',
  `payment_status` tinyint(4) DEFAULT NULL COMMENT '支付状态：0已失效 1待支付 2已完成 ',
  `payment_time` datetime DEFAULT NULL COMMENT '支付时间（购买时间）',
  `end_type` tinyint(4) DEFAULT NULL COMMENT '期限：1年 2月',
  `end_time` datetime DEFAULT NULL COMMENT '到期时间',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`order_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='订单信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

