CREATE TABLE `bid_order_refund_record` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `order_id` bigint(20) DEFAULT NULL COMMENT '订单编号',
  `gateway_id` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '网关流水',
  `refund_price` decimal(10,2) DEFAULT NULL COMMENT '退款金额',
  `refund_reason` tinyint(4) DEFAULT NULL COMMENT '退款原因：1个人原因 2商品原因 3其他',
  `refund_description` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '详细描述退款原因',
  `refund_time` datetime DEFAULT NULL COMMENT '退款时间（审核时间）',
  `check_user_id` bigint(20) DEFAULT NULL COMMENT '审核人',
  `check_user_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '审核人名称',
  `check_status` tinyint(4) DEFAULT NULL COMMENT '审核状态：1通过 0未通过',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间（申请时间）',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='订单退款记录表';
