--
-- Table structure for table `mes_check_standard`
--

DROP TABLE IF EXISTS `mes_check_standard`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `mes_check_standard` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '编号',
  `material_id` bigint(20) DEFAULT NULL COMMENT '物料分类',
  `check_item_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '检验项目名称',
  `check_type` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '检验类型：1来料检验2产品检验3生产采样',
  `max_value` double DEFAULT NULL COMMENT '标准值上限',
  `min_value` double DEFAULT NULL COMMENT '标准值下限',
  `remark` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=207 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='质检标准';
/*!40101 SET character_set_client = @saved_cs_client */;

