 SET character_set_client = utf8mb4 ;
CREATE TABLE `mes_material_check` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '编号',
  `serial_no` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '流水号',
  `material_requisition_id` bigint(20) DEFAULT NULL COMMENT '领料单编号',
  `material_requisition_no` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '领料单流水',
