  `check_quantity` double DEFAULT NULL COMMENT '抽检数量',
  `check_value` double DEFAULT NULL COMMENT '检验值',
  `max_value` double DEFAULT NULL COMMENT '标准值上限',
  `min_value` double DEFAULT NULL COMMENT '标准值下限',
