 SET character_set_client = utf8mb4 ;
CREATE TABLE `mes_mistake_proof` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '编号',
  `type` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '错误类型',
  `mistake_item` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '错误项',
  `mistake_result` longtext CHARACTER SET utf8 COLLATE utf8_general_ci COMMENT '导致错误结果',
  `prevent_method` longtext CHARACTER SET utf8 COLLATE utf8_general_ci COMMENT '预防手段',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='防错管理';
