 SET character_set_client = utf8mb4 ;
CREATE TABLE `mes_process_check` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '编号',
  `serial_no` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '流水号',
  `product_plan_id` bigint(20) DEFAULT NULL COMMENT '生产计划编号',
  `product_schedule_id` bigint(20) DEFAULT NULL COMMENT '计划排产编号',
  `product_line_id` bigint(20) DEFAULT NULL COMMENT '生产线编号',
  `product_job_id` bigint(20) DEFAULT NULL COMMENT '生产作业编号',
  `material_id` bigint(20) DEFAULT NULL COMMENT '物料档案编号',
  `check_standard_id` bigint(20) DEFAULT NULL COMMENT '检验标准编号',
  `product_quantity` double DEFAULT NULL COMMENT '生产数量',
  `check_quantity` double DEFAULT NULL COMMENT '采样数量',
  `check_value` double DEFAULT NULL COMMENT '检验值',
  `max_value` double DEFAULT NULL COMMENT '标准值上限',
  `min_value` double DEFAULT NULL COMMENT '标准值下限',
  `check_result` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '检验结果：0不合格1合格',
  `remark` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '备注',
  `check_user` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '检验人',
  `check_date` datetime DEFAULT NULL COMMENT '检验时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=58 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='生产采样单';
