 SET character_set_client = utf8mb4 ;
CREATE TABLE `scm_purchase_contract` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '编号',
  `contract_no` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '合同编号',
  `apply_id` bigint(20) DEFAULT NULL COMMENT '申请id',
  `apply_no` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '申请编号',
  `supplier_id` bigint(20) DEFAULT NULL COMMENT '供应商id',
  `amount` decimal(20,2) DEFAULT NULL COMMENT '金额',
