DROP TABLE IF EXISTS `scm_sale_contract_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `scm_sale_contract_detail` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '编号',
  `contract_id` bigint(20) DEFAULT NULL COMMENT '合同id',
  `material_id` bigint(20) DEFAULT NULL COMMENT '物料id',
  `price` decimal(10,2) DEFAULT NULL COMMENT '单价',
  `quantity` double DEFAULT NULL COMMENT '订货数量',
  `amount` decimal(20,2) DEFAULT NULL COMMENT '金额',
  `detail_remark` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=64 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='合同明细';
