INSERT INTO `sys_com_query` VALUES (1,'部门查询','dept_query',NULL,'SELECT t.`dept_id` dict_value,t.`dept_name` dict_label FROM sys_dept t','1',NULL),(2,'仓库查询','query_warehouse',NULL,'SELECT t.`id` dict_value,t.`name` dict_label FROM wms_warehouse t','1',NULL),(3,'供应商查询','query_supplier',NULL,'SELECT t.`id` dict_value,t.`name` dict_label FROM `scm_purchase_supplier` t WHERE t.audit_status=\'1\' and t.status=\'1\'','1',NULL),(4,'查询用户','query_user',NULL,'SELECT t.`user_id` dict_value,t.`nick_name` dict_label FROM `sys_user` t','1',NULL),(5,'客户查询','query_customer',NULL,'SELECT t.`id` dict_value,t.`name` dict_label FROM `scm_sale_customer` t WHERE t.`status`=\'1\'','1',NULL),(6,'查询销售订单','query_sale_order','查询销售订单','SELECT o.`order_no` dict_value, o.`order_no` dict_label FROM `scm_sale_order` o WHERE o.`audit_status`=\'2\'','1',NULL),(7,'查询采购计划','query_purchase_plan','查询采购计划','SELECT p.`id` dict_value, p.`purchase_plan_no` dict_label FROM `scm_purchase_plan` p','1',NULL),(8,'所有设备查询','query_equipment',NULL,'SELECT t.id dict_value,t.`name` dict_label,t.`batch_no` batchNo, t.`code`,t.`manufacturer`,t.`model`,t.`product_date` productDate FROM `mes_equipment` t','1',NULL),(9,'产品模型查询','query_product_model',NULL,'SELECT m.`id` dict_value,CONCAT(m.`model_name`,\'|\',t.`name`) dict_label FROM `mes_product_model` m \nLEFT JOIN `wms_material_info` t ON t.`id` = m.`material_id`','1',NULL),(10,'项目查询','query_project',NULL,'SELECT p.`id` dict_value,p.`name` dict_label FROM `mes_project` p WHERE p.`status` = \'1\'','1',NULL),(11,'BOM查询','query_bom',NULL,'SELECT t.`id` dict_value,CONCAT(t.`name`,\'|\',m.`name`) dict_label FROM `mes_product_bom` t\nLEFT JOIN `wms_material_info` m ON m.`id` = t.`product_id`','1',NULL),(12,'生产线查询','query_product_line',NULL,'SELECT t.`id` dict_value,t.`product_line_name` dict_label FROM `mes_factory_model` t ','1',NULL),(13,'工艺查询','process_query',NULL,'SELECT t.`id` dict_value,t.`process_name` dict_label FROM `mes_process_model` t ','1',NULL);
/*!40000 ALTER TABLE `sys_com_query` ENABLE KEYS */;
UNLOCK TABLES;

