DROP TABLE IF EXISTS `wms_out_warehouse_apply_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `wms_out_warehouse_apply_detail` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '编号',
  `apply_id` bigint(20) DEFAULT NULL COMMENT '申请单编号',
  `material_id` bigint(20) DEFAULT NULL COMMENT '物料档案编号',
  `warehouse_id` bigint(20) DEFAULT NULL COMMENT '仓库编号',
  `wh_location_id` bigint(20) DEFAULT NULL COMMENT '库位编号',
  `wh_region_id` bigint(20) DEFAULT NULL COMMENT '库区编号',
  `out_quantity` double DEFAULT NULL COMMENT '发货数量',
  `serial_no` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '序列号',
  `batch_no` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '生产批号',
  `product_date` date DEFAULT NULL COMMENT '生产日期',
  `manufacturer` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '生产单位',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=177 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='出库申请明细';
