--
-- Table structure for table `wms_warehouse_material_move`
--

DROP TABLE IF EXISTS `wms_warehouse_material_move`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `wms_warehouse_material_move` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '编号',
  `material_id` bigint(20) DEFAULT NULL COMMENT '物料档案id',
  `source_warehouse_id` bigint(20) DEFAULT NULL COMMENT '源仓库id',
  `source_region_id` bigint(20) DEFAULT NULL COMMENT '源库区id',
  `source_location_id` bigint(20) DEFAULT NULL COMMENT '源库位id',
  `batch_no` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '批号',
  `target_warehouse_id` bigint(20) DEFAULT NULL COMMENT '目标仓库id',
  `target_region_id` bigint(20) DEFAULT NULL COMMENT '目标库区id',
  `target_location_id` bigint(20) DEFAULT NULL COMMENT '目标库位id',
  `move_quantity` double DEFAULT NULL COMMENT '移出数量',
  `operate_date` datetime DEFAULT NULL COMMENT '移库时间',
  `operate_user` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '执行人',
  `reason` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '移库原因',
  `remark` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '备注',
  `status` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '状态：0未执行1已执行',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=68 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='移库记录';
/*!40101 SET character_set_client = @saved_cs_client */;

